    case MenuState::Worlds:{v.title="Singleplayer worlds";int start=m_menuController.scroll;for(int i=start;i<std::min(start+8,static_cast<int>(m_worlds.size()));++i){const auto& w=m_worlds[i];std::time_t time=static_cast<std::time_t>(w.lastPlayed);std::ostringstream date;auto* t=std::localtime(&time);if(t)date<<std::put_time(t,"%Y-%m-%d %H:%M");std::string label=(i==m_selectedWorld?"> ":"")+w.name+"  |  "+std::to_string(w.seed)+"  "+modeName(w.mode)+"  "+date.str();if(!w.error.empty())label=w.name+": "+w.error;v.widgets.push_back({1000+i,label,160,130.f+(i-start)*48,960,38});}
      const bool selected=m_selectedWorld>=0&&m_selectedWorld<static_cast<int>(m_worlds.size());v.widgets.push_back({4,"Play",160,540,220,44,selected&&m_worlds[m_selectedWorld].error.empty()});v.widgets.push_back({5,"New World",400,540,220,44});v.widgets.push_back({6,"Delete",640,540,220,44,selected});v.widgets.push_back({0,"Back",880,540,220,44});break;}
    case MenuState::Create:v.title="New world";button(20,"Name: "+(m_textTarget==20?m_worldName.display():m_worldName.text),170);button(21,"Seed (blank = random): "+(m_textTarget==21?m_seedText.display():m_seedText.text),234);button(22,std::string("Mode: ")+modeName(m_newMode),298);button(23,"Create and Play",390);button(0,"Cancel",454);break;
    case MenuState::Pause:v.title="Paused";button(7,"Resume",180);button(2,"Settings",244);button(8,"Keybinds",308);button(9,"Save & Quit",372);break;
    case MenuState::Settings:v.title="Settings";button(30,std::string(m_sessionActive?"Game Mode: ":"Default New World Mode: ")+modeName(m_sessionActive?m_player.gameMode():m_settings.defaultMode),124);button(31,"View distance: "+std::to_string(m_settings.viewDistance)+" chunks",180,true,(m_settings.viewDistance-2)/6.f);button(32,"Base FOV: "+std::to_string(static_cast<int>(m_settings.baseFov)),236,true,(m_settings.baseFov-30)/60);{std::ostringstream n;n<<std::fixed<<std::setprecision(2)<<m_settings.mouseSensitivity;button(33,"Mouse sensitivity: "+n.str(),292,true,(m_settings.mouseSensitivity-.01f)/.99f);}button(34,std::string("VSync: ")+(m_settings.vsync?"On":"Off"),348);button(35,std::string("Invert Y: ")+(m_settings.invertY?"On":"Off"),404);button(36,std::string("Raw mouse: ")+(glfwRawMouseMotionSupported()?(m_settings.rawMouseInput?"On":"Off"):"Unavailable"),460,glfwRawMouseMotionSupported());v.widgets.push_back({8,"Keybinds",240,532,380,44});v.widgets.push_back({0,"Done",660,532,380,44});break;
    case MenuState::Keybinds:{v.title=m_keybindCapture>=0?"Press a key or mouse button - Escape cancels":"Keybindings";int start=m_menuController.scroll;for(int i=start;i<std::min(start+8,static_cast<int>(SettingsState::ACTION_COUNT));++i){auto a=static_cast<KeyAction>(i);std::string label=std::string(SettingsState::actionLabel(a))+": "+SettingsState::bindingName(m_settings.key(a));if(m_keybindCapture==i)label+=" ...";v.widgets.push_back({100+i,label,200,132.f+(i-start)*48,680,38});v.widgets.push_back({200+i,"Reset",900,132.f+(i-start)*48,180,38});}v.widgets.push_back({10,"Reset All",240,540,380,44});v.widgets.push_back({0,"Done",660,540,380,44});break;}
    case MenuState::Delete:v.title="Delete world?";v.notice="Delete "+(m_selectedWorld>=0?m_worlds[m_selectedWorld].name:"")+"? This cannot be undone.";button(0,"Cancel",280);button(11,"Delete this world",344);break;
    case MenuState::Swap:v.title="Swap conflicting bindings?";button(0,"Cancel",280);button(12,"Swap",344);break;
