  if(m_menu==MenuState::Keybinds||m_menu==MenuState::Worlds){int count=m_menu==MenuState::Worlds?static_cast<int>(m_worlds.size()):static_cast<int>(SettingsState::ACTION_COUNT);if(count>8){v.widgets.push_back({80,"<",1126,132,28,38,m_menuController.scroll>0});v.widgets.push_back({81,">",1126,468,28,38,m_menuController.scroll+8<count});v.title+="  "+std::to_string(m_menuController.scroll+1)+"-"+std::to_string(std::min(count,m_menuController.scroll+8))+" / "+std::to_string(count);}}
